const item = $input.first().json;
let md = (item.output && item.output.relatorioMarkdown) ? item.output.relatorioMarkdown : '';

md = md.replace(/\|\s*\|/g, '|\n|');

md = md.replace(/([^\n])\n(\|.*\|)\s*\n(\|?\s*:?-{2,}:?\s*\|)/g, '$1\n\n$2\n$3');

function inlineMd(text) {
  if (!text) return '';
  return text
    .trim()
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    .replace(/`([^`]+)`/g, '<code>$1</code>');
}

function parseRow(line) {
  return line
    .trim()
    .replace(/^\|/, '')
    .replace(/\|$/, '')
    .split('|')
    .map(c => c.trim());
}

function isSeparatorRow(line) {
  return /^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$/.test(line);
}

function tableBlockToHtml(blockLines) {
  if (blockLines.length < 2 || !isSeparatorRow(blockLines[1])) {
    return blockLines.join('\n');
  }
  const header = parseRow(blockLines[0]);
  const bodyRows = blockLines.slice(2).map(parseRow);

  let html = '<table><thead><tr>';
  header.forEach(h => { html += `<th>${inlineMd(h)}</th>`; });
  html += '</tr></thead><tbody>';
  bodyRows.forEach(row => {
    html += '<tr>';
    row.forEach(cell => { html += `<td>${inlineMd(cell)}</td>`; });
    html += '</tr>';
  });
  html += '</tbody></table>';
  return html;
}

function normalizeTables(markdown) {
  const lines = markdown.split('\n');
  const isTableLine = (l) => /^\s*\|.*\|\s*$/.test(l.trim());

  const out = [];
  let buffer = [];
  let inTable = false;

  for (const line of lines) {
    if (isTableLine(line)) {
      buffer.push(line);
      inTable = true;
    } else {
      if (inTable) {
        out.push(tableBlockToHtml(buffer));
        buffer = [];
        inTable = false;
      }
      out.push(line);
    }
  }
  if (inTable && buffer.length) {
    out.push(tableBlockToHtml(buffer));
  }
  return out.join('\n');
}

const relatorioMarkdownNormalizado = normalizeTables(md);

return [{
  json: {
    ...item,
    output: {
      ...item.output,
      relatorioMarkdown: relatorioMarkdownNormalizado
    }
  }
}];

const inputJson = $input.first().json;

let raw = inputJson['URL do Alvo']
  || inputJson['URL do alvo']
  || inputJson['url']
  || inputJson['Url do Alvo']
  || '';

if (!raw) {
  for (const [key, value] of Object.entries(inputJson)) {
    if (typeof value === 'string' && value.trim() !== '' && !/responsavel|respons\u00e1vel/i.test(key)) {
      raw = value;
      break;
    }
  }
}

let urlStr = String(raw).trim();

const mdMatch = urlStr.match(/\]\((https?:\/\/[^\s)]+)\)/i);
if (mdMatch) {
  urlStr = mdMatch[1];
}

urlStr = urlStr.replace(/[\[\]<>]/g, '').trim();

if (!urlStr) {
  throw new Error('Nenhuma URL foi recebida do formulário. Campos recebidos: ' + JSON.stringify(inputJson));
}

if (!/^https?:\/\//i.test(urlStr)) {
  urlStr = 'https://' + urlStr;
}

const hostMatch = urlStr.match(/^https?:\/\/([^\/\?#]+)/i);
if (!hostMatch) {
  throw new Error('URL inválida fornecida: ' + raw);
}

let hostname = hostMatch[1].replace(/^[^@]*@/, '');
hostname = hostname.split(':')[0];

if (!hostname) {
  throw new Error('Não foi possível extrair o hostname da URL: ' + raw);
}

const responsavel = inputJson['Responsável pela Auditoria'] || inputJson['Responsavel pela Auditoria'] || 'Não informado';

return [{
  json: {
    targetUrl: urlStr,
    hostname: hostname,
    responsavel: responsavel,
    auditStartedAt: new Date().toISOString()
  }
}];

const data = $input.first().json;
const endpoints = data.endpoints || [];
const achados = [];

const PROTOCOLOS_INSEGUROS = ['SSL 2.0', 'SSL 3.0', 'TLS 1.0', 'TLS 1.1'];
const CIFRAS_FRACAS_REGEX = /(RC4|DES|3DES|MD5|NULL|EXPORT|anon)/i;

let protocoloSeguro = true;
let grade = 'N/A';
let detalhesProtocolos = [];
let cifrasFracas = [];

if (endpoints.length === 0) {
  achados.push({
    item: 'Conectividade SSL Labs',
    descricao: 'Não foi possível obter dados do SSL Labs para este host (host pode estar fora do ar, sem porta 443 aberta, ou análise ainda em ERROR).',
    severidade: 'Média'
  });
  protocoloSeguro = false;
} else {
  const ep = endpoints[0];
  grade = ep.grade || 'N/A';
  const details = ep.details || {};
  const protocols = details.protocols || [];

  detalhesProtocolos = protocols.map(p => `${p.name} ${p.version}`);

  const inseguros = protocols.filter(p => {
    const label = `${p.name} ${p.version}`;
    return PROTOCOLOS_INSEGUROS.some(ins => label.indexOf(ins.split(' ')[1]) !== -1 && label.indexOf(ins.split(' ')[0]) !== -1);
  });

  if (inseguros.length > 0) {
    protocoloSeguro = false;
    achados.push({
      item: 'Protocolos Criptográficos Obsoletos',
      descricao: `Foram detectados protocolos inseguros habilitados: ${inseguros.map(p => p.name + ' ' + p.version).join(', ')}. Esses protocolos possuem vulnerabilidades conhecidas (ex: POODLE, BEAST) e devem ser desabilitados.`,
      severidade: 'Alta'
    });
  }

  const suites = details.suites && details.suites.list ? details.suites.list : [];
  cifrasFracas = suites.filter(s => CIFRAS_FRACAS_REGEX.test(s.name));
  if (cifrasFracas.length > 0) {
    protocoloSeguro = false;
    achados.push({
      item: 'Cifras Criptográficas Fracas',
      descricao: `Foram identificadas cifras fracas ou obsoletas habilitadas no servidor: ${cifrasFracas.map(s => s.name).join(', ')}.`,
      severidade: 'Alta'
    });
  }

  if (grade && ['D', 'E', 'F', 'T', 'M'].includes(grade)) {
    protocoloSeguro = false;
    achados.push({
      item: 'Nota Geral SSL Labs Baixa',
      descricao: `O SSL Labs atribuiu nota "${grade}" para a configuração TLS deste servidor, indicando configuração insegura ou problemática.`,
      severidade: 'Alta'
    });
  } else if (grade && ['B', 'C'].includes(grade)) {
    achados.push({
      item: 'Nota Geral SSL Labs Intermediária',
      descricao: `O SSL Labs atribuiu nota "${grade}". Configuração aceitável, porém com espaço para melhorias (ex: HSTS, forward secrecy).`,
      severidade: 'Média'
    });
  }

  if (details.forwardSecrecy !== undefined && details.forwardSecrecy < 2) {
    achados.push({
      item: 'Forward Secrecy Insuficiente',
      descricao: 'O servidor não oferece suporte adequado a Forward Secrecy em todas as suítes, o que pode comprometer sessões passadas em caso de vazamento de chave privada.',
      severidade: 'Média'
    });
  }
}

return [{
  json: {
    ...data,
    protocoloSeguro,
    sslGrade: grade,
    protocolosDetectados: detalhesProtocolos,
    cifrasFracasDetectadas: cifrasFracas.map(s => s.name),
    achadosProtocolo: achados
  }
}];

const data = $input.first().json;
const endpoints = data.endpoints || [];
const certs = data.certs || [];
const achados = [];
let certificadoValido = true;
let certInfo = {};

const cert = certs.length > 0 ? certs[0] : null;

if (endpoints.length > 0 && endpoints[0].details && cert) {
  const agora = Date.now();
  const notAfter = cert.notAfter || null;
  const notBefore = cert.notBefore || null;

  certInfo = {
    issuer: cert.issuerSubject || 'Desconhecido',
    subject: cert.subject || 'Desconhecido',
    notBefore: notBefore ? new Date(notBefore).toISOString() : null,
    notAfter: notAfter ? new Date(notAfter).toISOString() : null,
    sigAlg: cert.sigAlg || 'Desconhecido',
    keyAlg: cert.keyAlg || 'Desconhecido',
    keySize: cert.keySize || null
  };

  if (notAfter && notAfter < agora) {
    certificadoValido = false;
    achados.push({
      item: 'Certificado Expirado',
      descricao: `O certificado digital expirou em ${certInfo.notAfter}. Certificados expirados quebram a confiança da conexão e devem ser renovados imediatamente.`,
      severidade: 'Alta'
    });
  } else if (notAfter) {
    const diasRestantes = Math.floor((notAfter - agora) / (1000 * 60 * 60 * 24));
    if (diasRestantes <= 30) {
      achados.push({
        item: 'Certificado Próximo da Expiração',
        descricao: `O certificado expira em ${diasRestantes} dia(s) (${certInfo.notAfter}). Recomenda-se renovação preventiva.`,
        severidade: 'Média'
      });
    }
  }

  if (/sha1/i.test(certInfo.sigAlg)) {
    certificadoValido = false;
    achados.push({
      item: 'Algoritmo de Assinatura Fraco',
      descricao: `O certificado utiliza o algoritmo de assinatura ${certInfo.sigAlg}, considerado fraco e obsoleto (vulnerável a colisões).`,
      severidade: 'Alta'
    });
  }

  if (certInfo.keyAlg === 'RSA' && certInfo.keySize && certInfo.keySize < 2048) {
    certificadoValido = false;
    achados.push({
      item: 'Tamanho de Chave Insuficiente',
      descricao: `A chave do certificado possui apenas ${certInfo.keySize} bits, abaixo do mínimo recomendado de 2048 bits para RSA.`,
      severidade: 'Alta'
    });
  }

  const certChains = endpoints[0].details.certChains;
  if (Array.isArray(certChains) && certChains.length > 0 && certChains[0].issues !== undefined) {
    if (certChains[0].issues !== 0) {
      certificadoValido = false;
      achados.push({
        item: 'Cadeia de Certificação com Problemas',
        descricao: 'A cadeia de certificação apresenta problemas (possível certificado autoassinado, incompleto ou não confiável por autoridades públicas).',
        severidade: 'Alta'
      });
    }
  }
} else {
  certificadoValido = false;
  achados.push({
    item: 'Certificado Não Verificável',
    descricao: 'Não foi possível obter informações do certificado digital deste servidor para análise.',
    severidade: 'Média'
  });
}

return [{
  json: {
    ...data,
    certificadoValido,
    certificadoInfo: certInfo,
    achadosCertificado: achados
  }
}];

const item = $input.first().json;

const MAX_ITENS_ARRAY = 15;
const MAX_CHARS_STRING = 300;

function truncStr(s) {
  if (typeof s !== 'string') return s;
  return s.length > MAX_CHARS_STRING ? s.slice(0, MAX_CHARS_STRING) + '... [truncado]' : s;
}

function truncArr(arr) {
  if (!Array.isArray(arr)) return [];
  const limitado = arr.slice(0, MAX_ITENS_ARRAY).map(a => {
    if (a && typeof a === 'object') {
      const copia = { ...a };
      if (copia.descricao) copia.descricao = truncStr(copia.descricao);
      return copia;
    }
    return truncStr(a);
  });
  if (arr.length > MAX_ITENS_ARRAY) {
    limitado.push({ aviso: `+${arr.length - MAX_ITENS_ARRAY} itens omitidos por limite de tamanho` });
  }
  return limitado;
}

const contexto = {
  alvo: item.targetUrl,
  hostname: item.hostname,
  responsavel: item.responsavel,
  auditStartedAt: item.auditStartedAt,
  sslGrade: item.sslGrade,
  protocoloConsideradoSeguroPelaColeta: item.protocoloSeguro,
  protocolosDetectados: truncArr(item.protocolosDetectados || []),
  cifrasFracasDetectadas: truncArr(item.cifrasFracasDetectadas || []),
  certificadoInfo: item.certificadoInfo ? {
    issuer: truncStr(item.certificadoInfo.issuer),
    subject: truncStr(item.certificadoInfo.subject),
    notBefore: item.certificadoInfo.notBefore,
    notAfter: item.certificadoInfo.notAfter,
    sigAlg: item.certificadoInfo.sigAlg,
    keyAlg: item.certificadoInfo.keyAlg,
    keySize: item.certificadoInfo.keySize
  } : {},
  statusCodeObtido: item.statusCodeObtido,
  headersAusentes: truncArr(item.headersAusentes || []),
  achadosBrutos: {
    protocoloSslTls: truncArr(item.achadosProtocolo || []),
    certificadoDigital: truncArr(item.achadosCertificado || []),
    configuracaoHttp: truncArr(item.achadosConfiguracao || [])
  }
};

let contextoTexto = JSON.stringify(contexto, null, 2);

const LIMITE_TOTAL = 6000;
if (contextoTexto.length > LIMITE_TOTAL) {
  contextoTexto = contextoTexto.slice(0, LIMITE_TOTAL) + '\n... [contexto truncado por limite de tamanho]';
}

return [{
  json: {
    ...item,
    contextoParaIA: contextoTexto
  }
}];

const item = $input.first().json;
const data = Array.isArray(item) ? item[0] : item;

const resumo = {
  responsavel: $('Alvo Fixo').first().json["Responsável pela Auditoria"],
  host: data.host,
  grade: data.sslGrade,
  protocoloSeguro: data.protocoloSeguro,
  protocolosDetectados: data.protocolosDetectados,
  cifrasFracasDetectadas: data.cifrasFracasDetectadas,
  headersAusentes: data.headersAusentes,
  achadosConfiguracao: data.achadosConfiguracao,
  achadosCertificado: data.achadosCertificado,
  certificadoValido: data.certificadoValido,
  hstsPolicy: data.endpoints?.[0]?.details?.hstsPolicy?.header || null,
};

return [{ json: resumo }];

